#include <algorithm>
#include <functional>
#include <queue>
#include <utility>
#include <vector>

int maxMeetings(std::vector<std::pair<int, int>> meetings)
{
    std::sort(meetings.begin(), meetings.end(), [](const auto& a, const auto& b) { return a.second < b.second; });
    int count = 0;
    long long freeAt = -(1LL << 62);
    for (auto [s, e] : meetings)
        if (s >= freeAt)
        {
            ++count;
            freeAt = e;
        }
    return count;
}

int roomsNeeded(const std::vector<std::pair<int, int>>& meetings)
{
    std::vector<std::pair<int, int>> events;
    events.reserve(meetings.size() * 2);
    for (auto [s, e] : meetings)
    {
        events.push_back({ s, 1 });
        events.push_back({ e, -1 });
    }
    std::sort(events.begin(), events.end());           // at equal times, -1 (an end) comes first
    int now = 0, most = 0;
    for (auto [t, change] : events) most = std::max(most, now += change);
    return most;
}

long long huffmanBits(const std::vector<long long>& frequencies)
{
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> heap(frequencies.begin(), frequencies.end());
    long long bits = 0;
    while (heap.size() > 1)
    {
        long long a = heap.top(); heap.pop();
        long long b = heap.top(); heap.pop();
        bits += a + b;
        heap.push(a + b);
    }
    return bits;
}

double fractionalKnapsack(std::vector<std::pair<double, double>> items, double capacity)
{
    double total = 0;
    std::vector<std::pair<double, double>> weighted;
    for (auto [w, v] : items)
    {
        if (w == 0) total += v;
        else weighted.push_back({ w, v });
    }
    std::sort(weighted.begin(), weighted.end(), [](const auto& a, const auto& b) { return a.second / a.first > b.second / b.first; });
    for (auto [w, v] : weighted)
    {
        if (capacity <= 0) break;
        double take = std::min(w, capacity);
        total += v * (take / w);
        capacity -= take;
    }
    return total;
}

unitTests:
TEST("one room") {
    CHECK_EQ(maxMeetings({ { 1, 4 }, { 3, 5 }, { 0, 6 }, { 5, 7 }, { 3, 9 }, { 5, 9 }, { 6, 10 }, { 8, 11 }, { 8, 12 }, { 2, 14 }, { 12, 16 } }), 4);
    CHECK_EQ(maxMeetings({ { 1, 5 }, { 5, 9 }, { 9, 10 } }), 3);
    CHECK_EQ(maxMeetings({ { 0, 100 }, { 1, 2 }, { 3, 4 } }), 2);
    CHECK_EQ(maxMeetings({}), 0);
    std::vector<std::pair<int, int>> big;
    for (int i = 0; i < 100000; ++i) big.push_back({ (i * 7919) % 100000 * 2, (i * 7919) % 100000 * 2 + 3 });
    CHECK_EQ(maxMeetings(big), 50000);
}
TEST("rooms") {
    CHECK_EQ(roomsNeeded({ { 0, 30 }, { 5, 10 }, { 15, 20 }, { 10, 15 }, { 25, 40 } }), 2);
    CHECK_EQ(roomsNeeded({ { 1, 5 }, { 5, 9 } }), 1);
    CHECK_EQ(roomsNeeded({ { 1, 5 }, { 1, 5 }, { 1, 5 } }), 3);
    CHECK_EQ(roomsNeeded({}), 0);
    std::vector<std::pair<int, int>> big;
    for (int i = 0; i < 100000; ++i) big.push_back({ i, i + 1000 });
    CHECK_EQ(roomsNeeded(big), 1000);
}
TEST("Huffman") {
    CHECK_EQ(huffmanBits({ 5, 9, 12, 13, 16, 45 }), 224LL);
    CHECK_EQ(huffmanBits({ 1, 1 }), 2LL);
    CHECK_EQ(huffmanBits({ 7 }), 0LL);
    CHECK_EQ(huffmanBits({}), 0LL);
    CHECK_EQ(huffmanBits({ 1, 1, 1, 1 }), 8LL);
    std::vector<long long> many(65536, 3);
    CHECK_EQ(huffmanBits(many), 3LL * 65536 * 16);
}
TEST("fractional knapsack") {
    CHECK_NEAR(fractionalKnapsack({ { 10, 60 }, { 20, 100 }, { 30, 120 } }, 50), 240.0, 1e-9);
    CHECK_NEAR(fractionalKnapsack({ { 10, 60 } }, 5), 30.0, 1e-9);
    CHECK_NEAR(fractionalKnapsack({ { 1, 1 }, { 0, 5 } }, 0), 5.0, 1e-9);
    CHECK_NEAR(fractionalKnapsack({}, 10), 0.0, 1e-9);
    CHECK_NEAR(fractionalKnapsack({ { 4, 8 }, { 2, 2 } }, 100), 10.0, 1e-9);
}

